module find_min_piles(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [7:0] strengths [0:7],\n    output reg [3:0] result,\n    output reg done\n);\n\n    localparam [3:0] S0_IDLE = 4'd0;\n    localparam [3:0] S1_SORT_START = 4'd1;\n    localparam [3:0] S2_SORT_ACTIVE = 4'd2;\n    localparam [3:0] S3_SORT_DONE = 4'd3;\n    localparam [3:0] S4_PROCESS_BOX = 4'd4;\n    localparam [3:0] S5_CHECK_PILE = 4'd5;\n    localparam [3:0] S6_INCREMENT_PILE = 4'd6;\n    localparam [3:0] S7_NEW_PILE = 4'd7;\n    localparam [3:0] S8_DONE = 4'd8;\n\n    reg [3:0] state;\n    reg [7:0] sorted [0:7];\n    reg [3:0] pile_heights [0:7];\n    reg [2:0] pass;\n    reg [2:0] i;\n    reg [2:0] current_box_index;\n    reg [2:0] current_pile_index;\n    reg [3:0] number_of_piles;\n    reg found;\n    integer j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S0_IDLE;\n            result <= 4'd0;\n            done <= 1'b0;\n            pass <= 3'd0;\n            i <= 3'd0;\n            current_box_index <= 3'd0;\n            current_pile_index <= 3'd0;\n            number_of_piles <= 4'd0;\n            found <= 1'b0;\n            for (j = 0; j < 8; j = j + 1) begin\n                sorted[j] <= 8'd0;\n                pile_heights[j] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                S0_IDLE: begin\n                    done <= 1'b0;\n                    if (start && n != 4'd0) begin\n                        for (j = 0; j < 8; j = j + 1) begin\n                            if (j < n)\n                                sorted[j] <= strengths[j];\n                            else\n                                sorted[j] <= 8'hFF;\n                            pile_heights[j] <= 4'd0;\n                        end\n                        pass <= 3'd0;\n                        i <= 3'd0;\n                        number_of_piles <= 4'd0;\n                        state <= S1_SORT_START;\n                    end else if (start && n == 4'd0) begin\n                        result <= 4'd0;\n                        done <= 1'b1;\n                        state <= S8_DONE;\n                    end\n                end\n\n                S1_SORT_START: begin\n                    if (n > 3'd1) begin\n                        pass <= 3'd0;\n                        i <= 3'd0;\n                        state <= S2_SORT_ACTIVE;\n                    end else begin\n                        state <= S3_SORT_DONE;\n                    end\n                end\n\n                S2_SORT_ACTIVE: begin\n                    if (pass < n - 3'd1) begin\n                        if (i < n - pass - 3'd1) begin\n                            if (sorted[i] > sorted[i + 1]) begin\n                                sorted[i] <= sorted[i + 1];\n                                sorted[i + 1] <= sorted[i];\n                            end\n                            i <= i + 3'd1;\n                            state <= S2_SORT_ACTIVE;\n                        end else begin\n                            i <= 3'd0;\n                            pass <= pass + 3'd1;\n                            state <= S2_SORT_ACTIVE;\n                        end\n                    end else begin\n                        state <= S3_SORT_DONE;\n                    end\n                end\n\n                S3_SORT_DONE: begin\n                    for (j = 0; j < 8; j = j + 1) begin\n                        pile_heights[j] <= 4'd0;\n                    end\n                    current_box_index <= 3'd0;\n                    number_of_piles <= 4'd0;\n                    state <= S4_PROCESS_BOX;\n                end\n\n                S4_PROCESS_BOX: begin\n                    if (current_box_index < n) begin\n                        current_pile_index <= 3'd0;\n                        found <= 1'b0;\n                        state <= S5_CHECK_PILE;\n                    end else begin\n                        result <= number_of_piles;\n                        done <= 1'b1;\n                        state <= S8_DONE;\n                    end\n                end\n\n                S5_CHECK_PILE: begin\n                    if (current_pile_index < number_of_piles) begin\n                        if (pile_heights[current_pile_index] <= sorted[current_box_index]) begin\n                            pile_heights[current_pile_index] <= pile_heights[current_pile_index] + 4'd1;\n                            found <= 1'b1;\n                            state <= S6_INCREMENT_PILE;\n                        end else begin\n                            current_pile_index <= current_pile_index + 3'd1;\n                            state <= S5_CHECK_PILE;\n                        end\n                    end else begin\n                        if (!found) begin\n                            state <= S7_NEW_PILE;\n                        end else begin\n                            state <= S6_INCREMENT_PILE;\n                        end\n                    end\n                end\n\n                S6_INCREMENT_PILE: begin\n                    current_box_index <= current_box_index + 3'd1;\n                    state <= S4_PROCESS_BOX;\n                end\n\n                S7_NEW_PILE: begin\n                    pile_heights[number_of_piles] <= 4'd1;\n                    number_of_piles <= number_of_piles + 4'd1;\n                    state <= S6_INCREMENT_PILE;\n                end\n\n                S8_DONE: begin\n                    done <= 1'b0;\n                    if (!start)\n                        state <= S0_IDLE;\n                end\n\n                default: state <= S0_IDLE;\n            endcase\n        end\n    end\n\nendmodule